static const char * const kLCProxyConsoleHTML =
"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>LiveProxy 控制台</title>\n<style>\n:root { color-scheme: dark; }\nbody { margin:0; font-family:-apple-system,BlinkMacSystemFont,\"Segoe UI\",sans-serif; background:#0d1117; color:#e6edf3; }\nheader { padding:18px 16px 10px; border-bottom:1px solid #21262d; }\nheader h1 { margin:0; font-size:20px; }\nheader .sub { color:#8b949e; font-size:13px; margin-top:4px; }\nmain { padding:16px; max-width:760px; margin:0 auto; }\n.card { background:#161b22; border:1px solid #30363d; border-radius:12px; padding:16px; margin-bottom:14px; }\n.card h2 { margin:0 0 12px; font-size:16px; }\n.row { display:flex; align-items:flex-start; justify-content:space-between; gap:12px; padding:8px 0; border-bottom:1px solid #21262d; }\n.row:last-child { border-bottom:none; }\n.k { color:#8b949e; flex:0 0 auto; }\n.v { font-weight:600; word-break:break-all; overflow-wrap:anywhere; text-align:right; min-width:0; }\ninput[type=text], input[type=number] { background:#0d1117; border:1px solid #30363d; color:#e6edf3; border-radius:8px; padding:8px 10px; width:100%; box-sizing:border-box; }\nbutton { background:#238636; color:#fff; border:none; border-radius:8px; padding:10px 14px; font-size:15px; cursor:pointer; }\nbutton.secondary { background:#30363d; }\n.switch { position:relative; width:48px; height:26px; display:inline-block; flex:0 0 auto; }\n.switch input { opacity:0; width:0; height:0; }\n.slider { position:absolute; cursor:pointer; inset:0; background:#30363d; border-radius:26px; transition:.2s; }\n.slider:before { content:\"\"; position:absolute; height:20px; width:20px; left:3px; top:3px; background:#fff; border-radius:50%; transition:.2s; }\n.switch input:checked + .slider { background:#238636; }\n.switch input:checked + .slider:before { transform:translateX(22px); }\ntable { width:100%; border-collapse:collapse; font-size:13px; }\nth,td { text-align:right; padding:6px 8px; border-bottom:1px solid #21262d; }\nth:first-child,td:first-child { text-align:left; }\n.msg { color:#58a6ff; font-size:13px; margin-top:8px; min-height:18px; }\n.badge { display:inline-block; padding:2px 8px; border-radius:10px; font-size:12px; }\n.badge.on { background:#1f6feb33; color:#58a6ff; }\n.badge.off { background:#f8514933; color:#f85149; }\n</style>\n</head>\n<body>\n<header>\n  <h1>LiveProxy 控制台</h1>\n  <div class=\"sub\">LiveContainer 任意 App 走 HTTP 代理 · 10 分钟流量统计</div>\n</header>\n<main>\n  <div class=\"card\">\n    <h2>代理控制</h2>\n    <div class=\"row\"><span class=\"k\">启用代理</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"proxyEnabled\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">丢弃非 TCP（UDP/QUIC）</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"blockNonTcp\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">调试日志</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"debugLogging\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">请求流量日志（按连接，滚动 2 MiB）</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"trafficLogging\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\"><span class=\"k\">启动显示代理加载横幅</span>\n      <label class=\"switch\"><input type=\"checkbox\" id=\"showProxyBanner\"><span class=\"slider\"></span></label>\n    </div>\n    <div class=\"row\" style=\"display:block\">\n      <label class=\"k\">上游模式</label>\n      <select id=\"proxyMode\">\n        <option value=\"custom\">自定义代理</option>\n        <option value=\"direct\">直连（无代理）</option>\n        <option value=\"kingcard\">王卡代理</option>\n      </select>\n      <div class=\"row\"><span class=\"k\">当前生效</span><span class=\"v\" id=\"effectiveMode\">…</span></div>\n      <div id=\"customFields\" style=\"margin-top:10px\">\n        <label class=\"k\">代理类型</label>\n        <input type=\"text\" id=\"proxyType\" value=\"http\">\n        <label class=\"k\">代理地址</label>\n        <input type=\"text\" id=\"proxyHost\" placeholder=\"192.168.1.10\">\n        <label class=\"k\">端口</label>\n        <input type=\"number\" id=\"proxyPort\" placeholder=\"8080\">\n      </div>\n      <div id=\"kingFields\" style=\"display:none;margin-top:10px\">\n        <label class=\"k\">取号手机号</label>\n        <input type=\"text\" id=\"kingPhone\" placeholder=\"18812341234\">\n        <label class=\"k\">Q-Type</label>\n        <input type=\"text\" id=\"kingQType\" placeholder=\"httpcom\">\n        <label class=\"k\">MCCMNC</label>\n        <input type=\"text\" id=\"kingMccmnc\" placeholder=\"46001 或 NULLNULL\">\n        <label class=\"k\">APN</label>\n        <input type=\"text\" id=\"kingApn\" placeholder=\"uninet / 3gnet\">\n        <label class=\"k\">网络类型</label>\n        <input type=\"text\" id=\"kingTypeName\" placeholder=\"MOBILE / WIFI / UNKNOW\">\n        <label class=\"k\">网络子类型</label>\n        <input type=\"number\" id=\"kingSubtype\" placeholder=\"0\">\n        <label class=\"k\">APN 附加信息</label>\n        <input type=\"text\" id=\"kingExtraInfo\" placeholder=\"uninet / 3gwap\">\n        <label class=\"k\">王卡状态</label>\n        <input type=\"number\" id=\"kingCardType\" placeholder=\"1\">\n        <div class=\"row\"><span class=\"k\">非蜂窝网络自动直连</span>\n          <label class=\"switch\"><input type=\"checkbox\" id=\"kingAutoDirectOnNonCellular\"><span class=\"slider\"></span></label>\n        </div>\n        <div class=\"row\"><span class=\"k\">转发器</span><span class=\"v\" id=\"kingRunning\">…</span></div>\n        <div class=\"row\"><span class=\"k\">最近取号</span><span class=\"v\" id=\"kingRefresh\">…</span></div>\n        <div class=\"row\"><span class=\"k\">来源</span><span class=\"v\" id=\"kingSource\">…</span></div>\n        <div class=\"row\"><span class=\"k\">HTTP 代理请求</span><span class=\"v\" id=\"statHttpRequests\">0</span></div>\n        <div class=\"row\"><span class=\"k\">HTTPS CONNECT</span><span class=\"v\" id=\"statHttpsConnects\">0</span></div>\n        <div class=\"row\"><span class=\"k\">直连兜底次数</span><span class=\"v\" id=\"statDirectFallbacks\">0</span></div>\n        <div class=\"row\"><span class=\"k\">凭证刷新次数</span><span class=\"v\" id=\"statRefreshCalls\">0</span></div>\n        <div class=\"msg\" id=\"recentDirectHosts\" style=\"white-space:pre-wrap;font-size:12px;color:#d29922\"></div>\n        <div class=\"msg\" id=\"kingError\"></div>\n        <div class=\"msg\" id=\"kingDiag\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e\"></div>\n        <div style=\"margin-top:8px\"><button class=\"secondary\" id=\"kingRefreshBtn\">立即刷新凭证</button><div class=\"msg\" id=\"kingManualResult\" style=\"white-space:pre-wrap;font-size:12px;color:#d29922\"></div></div><div class=\"row\" style=\"display:block;margin-top:10px\"><span class=\"k\">最近取号日志（20 条，含所有 App 触发）</span><div id=\"kingRefreshLog\" style=\"margin-top:6px;white-space:pre-wrap;font-size:12px;color:#8b949e;max-height:260px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px;\">暂无记录</div></div>\n      </div>\n      <div style=\"margin-top:12px\"><button id=\"saveConfig\">保存并应用</button></div>\n      <div style=\"margin-top:8px\"><button class=\"secondary\" id=\"testProxyBtn\">测试代理出口 IP</button></div>\n      <div class=\"msg\" id=\"proxyTestMsg\"></div>\n      <div class=\"msg\" id=\"proxyTestDetail\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e\"></div>\n      <div class=\"msg\" id=\"cfgMsg\"></div>\n    </div>\n  </div>\n\n  <div class=\"card\" id=\"selfcheckCard\">\n    <h2>就地自检（本进程能不能真的转发）</h2>\n    <div class=\"msg\" style=\"color:#8b949e;font-size:12px\">在**当前这个进程**里真去连王卡节点、发 CONNECT、读响应。私有 App 与共享 App 各跑一次，就能直接对照出差异。最长约 40 秒。</div>\n    <div style=\"margin-top:8px\"><button id=\"selfcheckBtn\">运行自检</button></div>\n    <div class=\"msg\" id=\"selfcheckMsg\" style=\"font-weight:600\"></div>\n    <div id=\"selfcheckDetail\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e;margin-top:6px;max-height:260px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n  </div>\n\n  <div class=\"card\" id=\"compareCard\">\n    <h2>私有 vs 共享 对比（首处差异）</h2>\n    <div class=\"msg\" style=\"color:#8b949e;font-size:12px\">来自所有进程写入的共享状态日志。若两边行为不同而每个字段都一样，说明差异不在这些可观测项里。</div>\n    <div id=\"compareTable\" style=\"white-space:pre-wrap;font-size:12px;margin-top:6px;max-height:260px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n  </div>\n\n  <div class=\"card\" id=\"diagCard\">\n    <h2>诊断（一键定位每个环节）</h2>\n    <div class=\"msg\" id=\"diagSummary\" style=\"font-size:14px;font-weight:600\">正在诊断…</div>\n    <div id=\"diagVerdict\" style=\"white-space:pre-wrap;font-size:13px;margin-top:8px\"></div>\n    <div style=\"margin-top:10px\"><button class=\"secondary\" id=\"diagReloadBtn\">重新诊断</button></div>\n\n    <div style=\"margin-top:14px\"><span class=\"k\">配置读写链路</span></div>\n    <div class=\"row\"><span class=\"k\">配置来源</span><span class=\"v\" id=\"diagCfgSource\">…</span></div>\n    <div class=\"row\"><span class=\"k\">生效 proxyMode</span><span class=\"v\" id=\"diagCfgMode\">…</span></div>\n    <div id=\"diagCfgTrail\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e;margin-top:4px\"></div>\n    <div id=\"diagCfgDirs\" style=\"white-space:pre-wrap;font-size:12px;margin-top:6px;max-height:220px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n\n    <div style=\"margin-top:14px\"><span class=\"k\">网络与上游</span></div>\n    <div class=\"row\"><span class=\"k\">探测到的网络参数</span><span class=\"v\" id=\"diagNetDetected\">…</span></div>\n    <div class=\"row\"><span class=\"k\">转发器 / 链端口</span><span class=\"v\" id=\"diagPorts\">…</span></div>\n    <div class=\"row\"><span class=\"k\">真监听探测</span><span class=\"v\" id=\"diagListen\">…</span></div>\n    <div class=\"row\"><span class=\"k\">路由已发布</span><span class=\"v\" id=\"diagRoute\">…</span></div>\n    <div class=\"row\"><span class=\"k\">代理池 / 身份来源</span><span class=\"v\" id=\"diagPool\">…</span></div>\n    <div id=\"diagUpstream\" style=\"white-space:pre-wrap;font-size:12px;color:#d29922;margin-top:6px\"></div>\n\n    <div style=\"margin-top:14px\"><span class=\"k\">运行环境（私有 vs 共享）</span></div>\n    <div id=\"diagSandbox\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e;max-height:200px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n    <div style=\"margin-top:10px\"><span class=\"k\">其它进程现场（跨进程对比）</span></div>\n    <div id=\"diagStatusTail\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e;max-height:220px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n    <div style=\"margin-top:10px\"><span class=\"k\">跨进程取号日志</span></div>\n    <div id=\"diagRefreshLog\" style=\"white-space:pre-wrap;font-size:12px;color:#8b949e;max-height:220px;overflow-y:auto;border:1px solid #30363d;border-radius:8px;padding:8px\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>流量统计（蜂窝网络）</h2>\n    <div class=\"row\"><span class=\"k\">当前网络</span><span class=\"v\" id=\"net\">…</span></div>\n    <div class=\"row\"><span class=\"k\">累计上传</span><span class=\"v\" id=\"totalUp\">…</span></div>\n    <div class=\"row\"><span class=\"k\">累计下载</span><span class=\"v\" id=\"totalDown\">…</span></div>\n    <div class=\"row\"><span class=\"k\">按 App 明细</span><span class=\"v\" id=\"appList\">…</span></div>\n    <table>\n      <thead><tr><th>时段（10 分钟）</th><th>上传</th><th>下载</th></tr></thead>\n      <tbody id=\"buckets\"></tbody>\n    </table>\n    <div style=\"margin-top:10px\"><button class=\"secondary\" id=\"resetStats\">清空统计</button></div>\n    <div class=\"msg\" id=\"statsMsg\"></div>\n  </div>\n\n  <div class=\"card\">\n    <h2>关于</h2>\n    <div class=\"row\"><span class=\"k\">版本</span><span class=\"v\" id=\"version\">…</span></div>\n    <div class=\"row\"><span class=\"k\">数据目录</span><span class=\"v\" id=\"dataDir\">…</span></div>\n    <div class=\"row\"><span class=\"k\">代理配置</span><span class=\"v\" id=\"confPath\">…</span></div>\n    <div class=\"row\"><span class=\"k\">请求流量日志</span><span class=\"v\" id=\"trafficLogPath\">…</span></div>\n    <div class=\"row\"><span class=\"k\">配置存在</span><span class=\"v\" id=\"confExists\">…</span></div>\n    <div class=\"row\"><span class=\"k\">核心代理数</span><span class=\"v\" id=\"proxyCount\">…</span></div>\n    <div class=\"row\"><span class=\"k\">控制端口</span><span class=\"v\" id=\"port\">…</span></div>\n    <p class=\"msg\">提示：修改代理地址或端口后，建议重启一次被代理 App，确保 WKWebView 等系统组件也使用新配置。</p>\n  </div>\n</main>\n<script>\n\"use strict\";\nconst $ = id => document.getElementById(id);\nconst api = async (path, opts) => {\n  const r = await fetch(path, {headers:{'Content-Type':'application/json'}, ...opts});\n  let j = null; try { j = await r.json(); } catch(e) {}\n  if (!r.ok) return {error:(j&&j.error)||('HTTP '+r.status)};\n  return j;\n};\nlet dirty = false;\nfunction markDirty() { dirty = true; }\nconst fmt = n => {\n  n = Number(n||0);\n  if (n >= 1024*1024*1024) return (n/1024/1024/1024).toFixed(2)+' GB';\n  if (n >= 1024*1024) return (n/1024/1024).toFixed(2)+' MB';\n  if (n >= 1024) return (n/1024).toFixed(1)+' KB';\n  return n+' B';\n};\nconst fmtTime = ts => {\n  const d = new Date(ts*1000);\n  const p = x => String(x).padStart(2,'0');\n  return d.getMonth()+1+'/'+d.getDate()+' '+p(d.getHours())+':'+p(d.getMinutes());\n};\nfunction syncModeUI() {\n  const mode = $('proxyMode').value;\n  $('customFields').style.display = mode === 'custom' ? 'block' : 'none';\n  $('kingFields').style.display = mode === 'kingcard' ? 'block' : 'none';\n  const labels = {custom:'自定义代理', direct:'直连（无代理）', kingcard:'王卡代理'};\n  $('effectiveMode').textContent = labels[mode] || mode || '—';\n}\nasync function loadStatus() {\n  const s = await api('/api/status');\n  if (s.error) { $('cfgMsg').textContent = '状态获取失败: '+s.error; return; }\n  const king = s.king || {};\n  $('kingRunning').textContent = king.running ? '运行中' : '未运行';\n  $('kingRefresh').textContent = king.lastRefresh || '—';\n  $('kingSource').textContent = king.lastSource || '—';\n  const fwStats = s.kingAggregate || {};\n  $('statHttpRequests').textContent = fwStats.httpRequests != null ? fwStats.httpRequests : '0';\n  $('statHttpsConnects').textContent = fwStats.httpsConnects != null ? fwStats.httpsConnects : '0';\n  $('statDirectFallbacks').textContent = fwStats.directFallbacks != null ? fwStats.directFallbacks : '0';\n  $('statRefreshCalls').textContent = fwStats.refreshCalls != null ? fwStats.refreshCalls : '0';\n  const directHosts = (fwStats.recentDirectHosts || []);\n  $('recentDirectHosts').textContent = directHosts.length ? ('最近直连兜底域名(全部App): ' + directHosts.join(', ')) : '';\n  $('kingError').textContent = king.lastError || '';\n  $('kingDiag').textContent = king.lastDiagnostics || '';\n  renderKingLog(king.refreshLog || []);\n  $('version').textContent = s.version || '—';\n  $('dataDir').textContent = s.dataDirectory || '—';\n  $('confPath').textContent = s.proxychainsConfPath || '—';\n  $('trafficLogPath').textContent = s.trafficLogPath || '—';\n  $('confExists').textContent = s.proxychainsConfExists ? '是' : '否';\n  $('proxyCount').textContent = s.proxyCount != null ? String(s.proxyCount) : '—';\n  $('port').textContent = s.serverPort || '—';\n  if (dirty) return;\n  $('proxyEnabled').checked = !!s.proxyEnabled;\n  $('blockNonTcp').checked = !!s.blockNonTcp;\n  $('debugLogging').checked = !!s.debugLogging;\n  $('trafficLogging').checked = s.trafficLogging != null ? !!s.trafficLogging : true;\n  $('showProxyBanner').checked = s.showProxyBanner != null ? !!s.showProxyBanner : true;\n  $('proxyMode').value = s.proxyMode || 'custom';\n  $('proxyType').value = s.proxyType || 'http';\n  $('proxyHost').value = s.proxyHost || '';\n  $('proxyPort').value = s.proxyPort || '';\n  $('kingPhone').value = s.kingPhone || '18812341234';\n  $('kingQType').value = s.kingQType || 'httpcom';\n  $('kingMccmnc').value = s.kingMccmnc || 'NULLNULL';\n  $('kingApn').value = s.kingApn || 'UNKNOW';\n  $('kingTypeName').value = s.kingTypeName || 'UNKNOW';\n  $('kingSubtype').value = s.kingSubtype != null ? s.kingSubtype : 0;\n  $('kingExtraInfo').value = s.kingExtraInfo || 'UNKNOW';\n  $('kingCardType').value = s.kingCardType != null ? s.kingCardType : 1;\n  $('kingAutoDirectOnNonCellular').checked = !!s.kingAutoDirectOnNonCellular;\n  syncModeUI();\n  const effective = s.effectiveMode || s.proxyMode || 'custom';\n  const labels = {custom:'自定义代理', direct:'直连（无代理）', kingcard:'王卡代理'};\n  $('effectiveMode').textContent = labels[effective] || effective;\n}\n// ---- 诊断面板 ----\n// 目标：让人（而不是我）能一眼看到**每个环节**的状态 —— 配置读取、转发器与监听、\n// 代理链端口、路由发布、凭证池与身份来源、上游分步失败、以及私有/共享两份运行环境。\nconst DIAG_LEVEL = {0:'OK', 1:'WARN', 2:'BAD'};\nconst DIAG_COLOR = {0:'#3fb950', 1:'#d29922', 2:'#f85149'};\nfunction fmtDiagVerdict(list) {\n  if (!list || !list.length) return '（无结论）';\n  return list.map(v => {\n    const lv = v.level|0;\n    return '[' + (DIAG_LEVEL[lv]||'?') + '] ' + v.text;\n  }).join('\\n');\n}\nfunction fmtDirs(list) {\n  if (!list || !list.length) return '（无候选目录）';\n  return list.map(d => {\n    const flags = [];\n    flags.push(d.isCanonical ? '权威' : '候选');\n    flags.push(d.writable ? '可写' : '不可写');\n    flags.push(d.settingsExists ? ('settings存在/' + (d.settingsReadable ? '可读' : '读不出')) : 'settings缺失');\n    flags.push(d.confExists ? 'conf存在' : 'conf缺失');\n    const size = d.settingsSize != null ? (' ' + d.settingsSize + 'B') : '';\n    const mode = d.settingsProxyMode ? (' mode=' + d.settingsProxyMode) : '';\n    return '· [' + flags.join(' ') + ']' + size + mode + '\\n  ' + d.dir;\n  }).join('\\n');\n}\nfunction fmtTail(lines) {\n  if (!lines || !lines.length) return '（无记录）';\n  return lines.map(l => {\n    try { const o = JSON.parse(l);\n      return 'pid=' + o.pid + (o.isSharedTweaks ? ' [共享]' : ' [私有]')\n        + ' ver=' + (o.ver||'?') + ' port=' + (o.port||0) + ' chain=' + (o.chainPort||0)\n        + ' run=' + (o.running?1:0) + ' listen=' + (o.listenOk?1:0)\n        + ' ready=' + (o.ready?1:0) + ' pool=' + JSON.stringify(o.pool||[])\n        + (o.up && o.up.recvFail ? (' recvFail=' + o.up.recvFail) : '')\n        + (o.vErr ? (' err=' + o.vErr) : '');\n    } catch (e) { return l; }\n  }).join('\\n');\n}\nasync function loadDiag() {\n  let d;\n  try { d = await api('/api/diag'); } catch (e) { $('diagSummary').textContent = '诊断请求失败: ' + e; return; }\n  if (d.error) { $('diagSummary').textContent = '诊断失败: ' + d.error; return; }\n  const lv = d.level|0;\n  $('diagSummary').textContent = (DIAG_LEVEL[lv]||'?') + ' — ' + (d.summary || '');\n  $('diagSummary').style.color = DIAG_COLOR[lv] || '#e6edf3';\n  $('diagVerdict').textContent = fmtDiagVerdict(d.verdict);\n\n  const cfg = d.configDiag || {};\n  $('diagCfgSource').textContent = cfg.source || '—';\n  $('diagCfgMode').textContent = cfg.effectiveProxyMode || '—';\n  $('diagCfgTrail').textContent = (cfg.trail || []).join('\\n');\n  $('diagCfgDirs').textContent = fmtDirs(cfg.directories);\n\n  const nd = d.networkDetected || {};\n  $('diagNetDetected').textContent = nd.typeName\n    ? (nd.typeName + ' / subtype=' + nd.subtype + ' / mccmnc=' + nd.mccmnc\n       + ' / cellular=' + (nd.cellular?1:0) + ' / satisfied=' + (nd.pathSatisfied?1:0))\n    : '—';\n  const k = d.king || {};\n  const ep = d.endpoints || {};\n  $('diagPorts').textContent = '转发器 ' + (k.forwarderPort||0) + ' / 链 ' + (k.chainProxyPort||0)\n    + ' / override ' + (ep.proxyOverridePort||0)\n    + ((k.forwarderPort && k.chainProxyPort === k.forwarderPort) ? ' ✓一致' : ' ✗不一致');\n  $('diagListen').textContent = 'listenProbeOk=' + (k.listenProbeOk||0)\n    + ' (listenFdValid=' + (k.listenFdValid||0) + ')'\n    + ((k.listenProbeOk === 0 && k.listenFdValid === 1) ? ' ← fd 正常但实际连不上' : '');\n  $('diagRoute').textContent = (k.routePublished ? '是' : '否') + (k.running ? ' / 转发器运行中' : ' / 转发器未运行');\n  $('diagPool').textContent = 'http=' + (k.liveHttpPool||0) + ' https=' + (k.liveHttpsPool||0)\n    + ' / 身份来源=' + (k.guidSource || '—');\n  const up = k.upstreamDiag || {};\n  $('diagUpstream').textContent = up.recvFail != null\n    ? ('上游：connectFail=' + up.connectFail + ' sendFail=' + up.sendFail + ' recvFail=' + up.recvFail\n       + ' (eof=' + (up.recvEof||0) + ' rst=' + (up.recvRst||0) + ' timeout=' + (up.recvTimeout||0) + ')'\n       + ' credCode=' + up.credCode + ' otherCode=' + up.otherCode + ' tunnelNoData=' + up.tunnelNoData\n       + (up.lastStage ? ('\\n最近失败：阶段=' + up.lastStage + ' 节点=' + up.lastProxy + ' code=' + up.lastCode + ' errno=' + up.lastErrno) : '')\n       + (up.req ? ('\\n请求结构：' + up.req) : '')\n       + (up.lastResp ? ('\\n上游响应：' + up.lastResp) : ''))\n    : '（无上游数据）';\n  const sb = (ep.sandbox) || {};\n  $('diagSandbox').textContent =\n    'bundle=' + (d.bundleId||'?') + '\\npid=' + (d.pid||0) + '\\ndylib=' + (sb.dylibPath||'')\n    + '\\nhome=' + (sb.home||'') + '\\nLC_HOME_PATH=' + (sb.lcHomePath||'')\n    + '\\n数据目录=' + (sb.dataDirectory||'')\n    + '\\n权威目录=' + (sb.canonicalDataDirectory||'')\n    + '\\n共享目录=' + (sb.sharedDataDirectory||'')\n    + '\\nguest目录=' + (sb.guestDataDirectory||'')\n    + '\\n候选目录:\\n' + ((sb.candidateDataDirectories||[]).map(x => '  · ' + x).join('\\n'));\n  $('diagStatusTail').textContent = fmtTail(d.statusTail);\n  $('compareTable').textContent = fmtCompare(d.statusTail);\n  $('diagRefreshLog').textContent = (d.refreshLogShared || []).map(l => {\n    try { const o = JSON.parse(l); return fmtLogTime(o.ts) + ' [' + (o.ok?'成功':'失败') + '] pid=' + o.pid + ' ' + o.src + '\\n' + (o.msg||''); }\n    catch (e) { return l; }\n  }).join('\\n---\\n');\n}\n$('diagReloadBtn').onclick = loadDiag;\n\n// ---- 就地自检 ----\nfunction fmtSelfcheck(d) {\n  if (!d) return '';\n  const lines = [];\n  lines.push('进程: pid=' + (d.pid||'?') + ' bundle=' + (d.bundleId||'?')\n    + (d.isSharedTweaks ? '  [共享 tweaks 路径]' : '  [私有 tweaks 路径]'));\n  lines.push('结论: ' + (d.ok ? '✅ 能转发' : '❌ 无法转发') + '  stage=' + (d.stage||'?'));\n  if (d.forwarderPort != null) lines.push('转发器端口=' + d.forwarderPort\n    + ' 真监听=' + (d.listenProbeOk?1:0) + ' 路由已发布=' + (d.routePublished?1:0));\n  lines.push('池: http=' + (d.poolHttp||0) + ' https=' + (d.poolHttps||0)\n    + ' / 有GUID=' + (d.hasGuid?1:0) + ' 有Token=' + (d.hasToken?1:0)\n    + ' / 身份来源=' + (d.guidSource || '—'));\n  if (d.lastError) lines.push('lastError: ' + d.lastError);\n  (d.attempts||[]).forEach((a,i) => {\n    lines.push('  #' + (i+1) + ' ' + a.proxy\n      + '  connect=' + (a.connectOK?('ok'):('FAIL errno='+a.connectErrno))\n      + ' send=' + (a.sendOK?'ok':'FAIL')\n      + ' recv=' + a.recvBytes + 'B'\n      + (a.recvBytes === 0 ? (a.recvEOF ? ' (对端关闭)' : (' (errno='+a.recvErrno+')')) : '')\n      + ' code=' + a.code\n      + (a.resp ? ('\\n       resp: ' + a.resp) : ''));\n  });\n  lines.push('');\n  lines.push(d.interpretation || '');\n  return lines.join('\\n');\n}\nasync function runSelfcheck() {\n  const btn = $('selfcheckBtn');\n  btn.disabled = true;\n  $('selfcheckMsg').textContent = '自检中…（真实网络往返，最长约 40 秒）';\n  $('selfcheckMsg').style.color = '#d29922';\n  try {\n    const d = await api('/api/selfcheck');\n    $('selfcheckMsg').textContent = (d.ok ? '✅ 本进程能转发' : '❌ 本进程无法转发') + ' — ' + (d.stage || '');\n    $('selfcheckMsg').style.color = d.ok ? '#3fb950' : '#f85149';\n    $('selfcheckDetail').textContent = fmtSelfcheck(d);\n  } catch (e) {\n    $('selfcheckMsg').textContent = '自检请求失败: ' + e;\n    $('selfcheckMsg').style.color = '#f85149';\n  } finally {\n    btn.disabled = false;\n  }\n}\n$('selfcheckBtn').onclick = runSelfcheck;\n\n// ---- 私有 vs 共享 对比 ----\n// 取共享状态日志里最近的快照，按 isSharedTweaks 分成两组，逐字段找出**首处差异**。\nfunction fmtCompare(lines) {\n  if (!lines || !lines.length) return '（暂无跨进程快照；两个环境各跑一会儿再看）';\n  const seen = new Map();\n  lines.forEach(l => {\n    try {\n      const o = JSON.parse(l);\n      const key = (o.isSharedTweaks ? 'shared' : 'private');\n      if (!seen.has(key)) seen.set(key, { o, n: 0 });\n      seen.get(key).n++;\n    } catch (e) {}\n  });\n  const priv = seen.get('private'), sh = seen.get('shared');\n  const out = [];\n  out.push('样本：私有 ' + (priv?priv.n:0) + ' 条，共享 ' + (sh?sh.n:0) + ' 条');\n  if (!priv || !sh) {\n    out.push('⚠ 需要两个环境都运行过（各自打开 App 用一会儿）才能对比。');\n    if (priv) out.push('（已看到私有进程：pid=' + priv.o.pid + ' bundle=' + priv.o.bundle + '）');\n    if (sh) out.push('（已看到共享进程：pid=' + sh.o.pid + ' bundle=' + sh.o.bundle + '）');\n    return out.join('\\n');\n  }\n  const a = priv.o, b = sh.o;\n  out.push('私有 pid=' + a.pid + ' bundle=' + a.bundle + ' ver=' + a.ver);\n  out.push('共享 pid=' + b.pid + ' bundle=' + b.bundle + ' ver=' + b.ver);\n  const FIELDS = [\n    ['ver','版本'], ['port','转发器端口'], ['chainPort','链端口'], ['overridePort','override'],\n    ['running','运行'], ['listenOk','真监听'], ['ready','就绪'],\n    ['vErr','lastError'],\n  ];\n  let firstDiff = null;\n  FIELDS.forEach(([k,label]) => {\n    const av = a[k], bv = b[k];\n    const same = JSON.stringify(av) === JSON.stringify(bv);\n    if (!same && firstDiff === null) firstDiff = label + '（私有=' + JSON.stringify(av) + ' 共享=' + JSON.stringify(bv) + '）';\n    out.push((same ? '  = ' : '  ≠ ') + label + ': 私有=' + JSON.stringify(av) + ' 共享=' + JSON.stringify(bv));\n  });\n  // 上游分步计数与池\n  const upa = a.up || {}, upb = b.up || {};\n  const UPS = [['connectFail','上游连接失败'],['sendFail','上游发送失败'],['recvFail','上游零字节'],\n               ['recvEof','  其中对端关闭'],['recvRst','  其中被重置'],['recvTimeout','  其中读超时'],\n               ['credCode','凭证被拒(820/821/823)'],['otherCode','其它状态码'],['tunnelNoData','隧道无数据']];\n  UPS.forEach(([k,label]) => {\n    const av = upa[k], bv = upb[k];\n    const same = JSON.stringify(av) === JSON.stringify(bv);\n    if (!same && firstDiff === null && av != null) firstDiff = label + '（私有=' + av + ' 共享=' + bv + '）';\n    out.push((same ? '  = ' : '  ≠ ') + label + ': 私有=' + (av==null?'—':av) + ' 共享=' + (bv==null?'—':bv));\n  });\n  ['pool','connects','reject','clients'].forEach(k => {\n    const av = a[k], bv = b[k];\n    out.push((JSON.stringify(av)===JSON.stringify(bv) ? '  = ' : '  ≠ ') + k + ': 私有=' + JSON.stringify(av) + ' 共享=' + JSON.stringify(bv));\n  });\n  if (upa.req || upb.req) {\n    out.push('  私有请求: ' + (upa.req || '—'));\n    out.push('  共享请求: ' + (upb.req || '—'));\n  }\n  out.push('');\n  out.push(firstDiff ? ('★ 首处差异：' + firstDiff) : '★ 未发现差异 —— 差异不在这批可观测项里。');\n  return out.join('\\n');\n}\n\nasync function loadStats() {\n  const s = await api('/api/stats');\n  if (s.error) { $('statsMsg').textContent = '统计获取失败: '+s.error; return; }\n  $('net').innerHTML = s.cellular ? \"<span class='badge on'>蜂窝</span>\" : \"<span class='badge off'>Wi-Fi/其他</span>\";\n  $('totalUp').textContent = fmt(s.totalUpload);\n  $('totalDown').textContent = fmt(s.totalDownload);\n  const apps = (s.apps||[]).map(a => a.bundleId+' '+fmt(a.totalUpload)+'↑ '+fmt(a.totalDownload)+'↓').join('<br>') || '—';\n  $('appList').innerHTML = apps;\n  const rows = (s.buckets||[]).slice(-48).reverse().map(b =>\n    '<tr><td>'+fmtTime(b.start)+'</td><td>'+fmt(b.upload)+'</td><td>'+fmt(b.download)+'</td></tr>'\n  ).join('');\n  $('buckets').innerHTML = rows || '<tr><td colspan=3 style=\"text-align:center;color:#8b949e\">暂无数据</td></tr>';\n}\n$('proxyMode').onchange = () => { markDirty(); syncModeUI(); };\n['proxyEnabled','blockNonTcp','debugLogging','trafficLogging','showProxyBanner','kingAutoDirectOnNonCellular'].forEach(id => { $(id).addEventListener('change', markDirty); });\n['proxyType','proxyHost','proxyPort','kingPhone','kingQType','kingMccmnc','kingApn','kingTypeName','kingSubtype','kingExtraInfo','kingCardType'].forEach(id => { $(id).addEventListener('input', markDirty); });\nfunction fmtLogTime(ts) {\n  const d = new Date(ts*1000);\n  const p = x => String(x).padStart(2,'0');\n  return p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());\n}\nfunction renderKingLog(log) {\n  const el = $('kingRefreshLog');\n  if (!log.length) { el.textContent = '暂无记录'; return; }\n  el.textContent = log.map(e => {\n    const head = fmtLogTime(e.ts) + ' [' + (e.ok ? '成功' : '失败') + ']'\n      + (e.src ? ' ' + e.src : '') + (e.ms != null ? ' ' + Math.round(e.ms) + 'ms' : '');\n    return head + (e.msg ? '\\n' + e.msg : '');\n  }).join('\\n----------------------------------------\\n');\n}\nlet manualRefreshing = false;\n$('kingRefreshBtn').onclick = async () => {\n  if (manualRefreshing) return;\n  manualRefreshing = true;\n  const btn = $('kingRefreshBtn');\n  btn.disabled = true;\n  $('kingManualResult').textContent = '刷新中…（正在取号，最长约 30 秒，请勿重复点击）';\n  $('kingError').textContent = '刷新中…';\n  try {\n    const r = await api('/api/king/refresh', {method:'POST', body:'{}'});\n    if (r.error) {\n      $('kingManualResult').textContent = '刷新失败: ' + r.error;\n    } else {\n      const log = (r.refreshLog || [])[0];\n      const head = log ? ('本次取号 ' + (log.ok ? '成功' : '失败')\n        + (log.src ? ' · ' + log.src : '')\n        + (log.ms != null ? ' · ' + Math.round(log.ms) + 'ms' : '') + '\\n') : '';\n      $('kingManualResult').textContent = head + ((log && log.msg) || r.lastError || '');\n      $('kingError').textContent = r.lastRefreshSuccess ? '刷新成功' : (r.lastError || '刷新失败');\n    }\n  } catch (e) {\n    $('kingManualResult').textContent = '请求异常: ' + e;\n  } finally {\n    manualRefreshing = false;\n    btn.disabled = false;\n    loadStatus();\n  }\n};\n$('saveConfig').onclick = async () => {\n  const body = {\n    proxyEnabled: $('proxyEnabled').checked,\n    blockNonTcp: $('blockNonTcp').checked,\n    debugLogging: $('debugLogging').checked,\n    trafficLogging: $('trafficLogging').checked,\n    showProxyBanner: $('showProxyBanner').checked,\n    proxyMode: $('proxyMode').value,\n    proxyType: $('proxyType').value.trim() || 'http',\n    proxyHost: $('proxyHost').value.trim(),\n    proxyPort: parseInt($('proxyPort').value || '0', 10),\n    kingPhone: $('kingPhone').value.trim() || '18812341234',\n    kingQType: $('kingQType').value.trim() || 'httpcom',\n    kingMccmnc: $('kingMccmnc').value.trim() || 'NULLNULL',\n    kingApn: $('kingApn').value.trim() || 'UNKNOW',\n    kingTypeName: $('kingTypeName').value.trim() || 'UNKNOW',\n    kingSubtype: parseInt($('kingSubtype').value || '0', 10),\n    kingExtraInfo: $('kingExtraInfo').value.trim() || 'UNKNOW',\n    kingCardType: parseInt($('kingCardType').value || '1', 10),\n    kingAutoDirectOnNonCellular: $('kingAutoDirectOnNonCellular').checked\n  };\n  const r = await api('/api/config', {method:'POST', body:JSON.stringify(body)});\n  if (!r.error) dirty = false;\n  $('cfgMsg').textContent = r.error ? ('保存失败: '+r.error) : '已保存并应用（部分系统组件需重启 App 生效）';\n  loadStatus();\n};\n$('testProxyBtn').onclick = async () => {\n  const sources = [\n    'http://ip.3322.net',\n    'http://ifconfig.me/ip',\n    'http://icanhazip.com',\n    'http://members.3322.org/dyndns/getip',\n    'http://ip-api.com/line/?fields=query',\n    'http://myip.ipip.net'\n  ];\n  $('proxyTestMsg').textContent = '开始并发测试…';\n  $('proxyTestDetail').textContent = '';\n  const results = await Promise.all(sources.map(async (url) => {\n    const r = await api('/api/proxy-test-one', {method:'POST', body: JSON.stringify({url})});\n    const info = r.ip ? ('IP '+r.ip) : ('rc='+(r.rc!=null?r.rc:'?')+(r.body?' '+r.body:''));\n    $('proxyTestDetail').textContent += url + ' -> ' + info + '\\n';\n    return {url, r};\n  }));\n  const found = results.find(x => x.r.ok && x.r.ip);\n  if (found) {\n    $('proxyTestMsg').textContent = '出口 IP: '+found.r.ip+'（'+found.url+'，共测试 '+sources.length+' 个源，并发完成）';\n  } else {\n    $('proxyTestMsg').textContent = '所有 IP 源均失败，请检查代理/转发器';\n  }\n};\n$('resetStats').onclick = async () => {\n  const r = await api('/api/reset-stats', {method:'POST', body:'{}'});\n  $('statsMsg').textContent = r.error ? ('失败: '+r.error) : '统计已清空';\n  loadStats();\n};\nasync function refresh() { await loadStatus(); await loadStats(); await loadDiag(); }\nsetInterval(refresh, 5000);\nrefresh();\n</script>\n</body>\n</html>\n";
